def write(rel, text):
    p = ROOT / rel
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(text, encoding="utf-8", newline="\n")
    print("WRITE", rel)

social_md = '# Social Intelligence — external signals inside vfresearch\n\nStatus: embedded into the existing `vfresearch` + Velvet Visual Foundry flow. This is **not** a new pack, scheduler, scraper runtime, analytics source of truth, or publishing authority.\n\n## Purpose\n\nGive the existing Instagram decision pipeline current, evidence-backed external signals without contaminating Velvet Factory voice or replacing canonical Instagram data.\n\nThe flow is:\n\n`public external signal → normalized SocialResearchPacket → content-matrix candidates → saturation/anti-generic/format/hook/retention → vfcopy + Visual Foundry → vfigos → verified Instagram Insights → vfinsights learning`\n\n## Source authority\n\n1. **Our own account and posts:** Instagram MCP remains canonical for profile/media/Insights. Never scrape our own metrics when the Graph/MCP can return them.\n2. **External public research:** use `WebSearch` / `WebFetch` first when they provide enough evidence. Browser/manual public-page inspection is allowed when authorized by the tool surface.\n3. **Optional scraping provider:** Apify or another provider may be used only for public material when a normal web source is insufficient. Provider choice is an adapter detail, not a system dependency.\n4. `cporter202/social-media-scraping-apis` is a **provider-discovery catalogue only**. Do not vendor, clone, or treat its thousands of listings as trusted integrations.\n5. No cookies copied from owner sessions. No private/auth-only scraping. No login bypass. No automated likes, follows, comments, DMs, or engagement manipulation.\n6. Costed scraping must be bounded and visible. Prefer cached public evidence and narrow watchlists over broad crawling.\n\n## SocialResearchPacket\n\nCanonical schema: `social-research-packet.schema.json`.\n\nEvery signal keeps provenance:\n\n- `source_url`\n- author/handle when public\n- `published_at` when known\n- `observed_at`\n- media type\n- public observed metrics only when actually returned\n- topic / mechanic tags\n- provider\n- evidence quality\n- raw reference or note\n\nMissing metric stays absent/null. Never coerce unavailable → `0`.\n\nThe deterministic helper is:\n\n```bash\npython3 scripts/vf_social_intelligence.py normalize-signals --input raw.json --output packet.json --window-start 2026-09-07 --window-end 2026-09-14\npython3 scripts/vf_social_intelligence.py validate-packet packet.json\n```\n\nThe helper normalizes and validates facts. It does **not** invent trends, virality, sentiment, or recommendations.\n\n## Reference Reel / short-form analyzer\n\nCanonical schema: `reference-pattern.schema.json`.\n\nA reference is used to learn **mechanics**, never to copy wording, identity, branding, footage, or protected creative expression.\n\nAllowed extracted mechanics include:\n\n- duration\n- first spoken beat\n- first visual change\n- shot/event count\n- overlay count\n- reveal timing when explicitly annotated\n- CTA type when explicitly observed\n- hook/visual/narrative mechanic tags supplied by an analyst/model with source evidence\n\nFlow:\n\n`public reference URL → lawful acquisition / transcript / vision notes → vf_social_intelligence.py reference-pattern → REFERENCE-PATTERN.json → format_selection / hook_tournament / retention_pass`\n\nHyperFrames / existing render tools remain the renderer. VoiceStudio remains the speech layer when used. The reference analyzer is research only.\n\n## Content Matrix operator\n\nThe matrix is an **ideation operator inside `INSTAGRAM-CONTENT-DECISION.json`**, not a post generator or publisher.\n\nUse 3–5 Velvet-specific content pillars and these eight angle families:\n\n1. actionable\n2. motivational\n3. analytical\n4. contrarian\n5. observation\n6. x_vs_y\n7. present_vs_future\n8. listicle\n\nEvery candidate must bind to real Velvet Factory proof (`proofRef`) or current external evidence (`source_refs`). A generic candidate with no proof is rejected before expensive generation.\n\nA single strong `print.done` / real-proof opportunity may record `not_applicable_single_evidence`; the stage may never be silently skipped.\n\n## Outlier / trend radar\n\nExternal metrics are contextual, not directly comparable across accounts. An outlier score is allowed only when a baseline for the **same source/account and same metric family** exists. Otherwise write `outlier_score: null`.\n\nNo global “virality score”. No synthetic benchmark pretending to be measured data.\n\nRecommended watchlist behaviour:\n\n- narrow named public sources\n- verified dates\n- 7–30 day windows depending on the research task\n- source-relative baselines\n- clustering after collection, not before\n- `why_now` must cite source refs\n- `nothing-solid` is valid when evidence is weak\n\n## Learning bridge\n\n`vfinsights` writes `CREATIVE-PERFORMANCE-PROFILE.json` from verified `posts.csv` plus optional qualitative annotations in `data/creative-annotations.csv`.\n\nThe profile is a **prior**, never a truth override:\n\n- each promoted pattern needs at least 3 measured posts for that pattern\n- missing metrics stay null\n- no composite virality score\n- measured history may influence hook/format ranking, but proof, rights, brand fit, and quality gates still win\n\n## External source inspirations embedded\n\n- `charlie947/social-media-skills`: content matrix, data-backed post scoring, reference-Reel mechanics, date-verified niche research.\n- `cporter202/automate-for-growth`: batching as cheap candidate expansion + feedback-loop discipline only; no ViralWave dependency.\n- `cporter202/social-media-scraping-apis`: provider discovery only; no clone/runtime dependency.\n\nAll three stay registered in `LINKS.json` for recurring review.\n'
packet_schema = {'$schema': 'https://json-schema.org/draft/2020-12/schema', '$id': 'https://velvetos.local/schema/social-research-packet.schema.json', 'title': 'VelvetOS SocialResearchPacket', 'type': 'object', 'required': ['schemaVersion', 'window', 'sources', 'signals', 'opportunities', 'risks'], 'properties': {'schemaVersion': {'const': '1.0'}, 'window': {'type': 'object', 'required': ['start', 'end'], 'properties': {'start': {'type': 'string'}, 'end': {'type': 'string'}}, 'additionalProperties': False}, 'sources': {'type': 'array', 'items': {'type': 'object', 'required': ['url', 'provider'], 'properties': {'url': {'type': 'string', 'pattern': '^https?://'}, 'provider': {'type': 'string'}, 'observed_at': {'type': ['string', 'null']}, 'note': {'type': ['string', 'null']}}, 'additionalProperties': True}}, 'signals': {'type': 'array', 'items': {'type': 'object', 'required': ['source_url', 'provider', 'observed_at', 'metrics'], 'properties': {'source_url': {'type': 'string', 'pattern': '^https?://'}, 'provider': {'type': 'string'}, 'author': {'type': ['string', 'null']}, 'published_at': {'type': ['string', 'null']}, 'observed_at': {'type': 'string'}, 'media_type': {'type': ['string', 'null']}, 'topic': {'type': ['string', 'null']}, 'hook_mechanic': {'type': ['string', 'null']}, 'visual_mechanic': {'type': ['string', 'null']}, 'narrative_mechanic': {'type': ['string', 'null']}, 'outlier_score': {'type': ['number', 'null']}, 'evidence_quality': {'type': ['string', 'null']}, 'metrics': {'type': 'object', 'additionalProperties': {'type': ['number', 'integer', 'null']}}}, 'additionalProperties': True}}, 'opportunities': {'type': 'array', 'items': {'type': 'object', 'required': ['why_now', 'velvet_relevance', 'source_refs'], 'properties': {'why_now': {'type': 'string'}, 'velvet_relevance': {'type': 'string'}, 'recommended_format': {'type': ['string', 'null']}, 'usable_proof': {'type': ['string', 'null']}, 'source_refs': {'type': 'array', 'items': {'type': 'string'}}}, 'additionalProperties': True}}, 'risks': {'type': 'array', 'items': {'type': 'string'}}}, 'additionalProperties': True}
reference_schema = {'$schema': 'https://json-schema.org/draft/2020-12/schema', '$id': 'https://velvetos.local/schema/reference-pattern.schema.json', 'title': 'VelvetOS ReferencePattern', 'type': 'object', 'required': ['schemaVersion', 'source_url', 'observed', 'mechanics', 'provenance', 'copyingForbidden'], 'properties': {'schemaVersion': {'const': '1.0'}, 'source_url': {'type': 'string', 'pattern': '^https?://'}, 'observed': {'type': 'object', 'properties': {'duration_seconds': {'type': ['number', 'null']}, 'first_spoken_at_seconds': {'type': ['number', 'null']}, 'first_visual_change_at_seconds': {'type': ['number', 'null']}, 'event_count': {'type': 'integer', 'minimum': 0}, 'overlay_count': {'type': 'integer', 'minimum': 0}, 'reveal_at_seconds': {'type': ['number', 'null']}}, 'additionalProperties': True}, 'mechanics': {'type': 'object', 'properties': {'hook_mechanic': {'type': ['string', 'null']}, 'visual_mechanic': {'type': ['string', 'null']}, 'narrative_mechanic': {'type': ['string', 'null']}, 'cta_type': {'type': ['string', 'null']}}, 'additionalProperties': True}, 'provenance': {'type': 'object', 'required': ['provider'], 'properties': {'provider': {'type': 'string'}, 'captured_at': {'type': ['string', 'null']}, 'raw_ref': {'type': ['string', 'null']}}, 'additionalProperties': True}, 'copyingForbidden': {'const': True}}, 'additionalProperties': True}
script = '#!/usr/bin/env python3\n"""Normalize external public social evidence for VelvetOS. No network. No send.\n\nThis helper deliberately does not scrape. Acquisition is provider-specific and happens\nthrough authorized web/provider tools. This file normalizes the resulting public facts\ninto stable research contracts.\n\nExamples:\n  python3 scripts/vf_social_intelligence.py normalize-signals --input raw.json --output packet.json --window-start 2026-09-07 --window-end 2026-09-14\n  python3 scripts/vf_social_intelligence.py validate-packet packet.json\n  python3 scripts/vf_social_intelligence.py reference-pattern --input reference-observations.json --output reference-pattern.json\n  python3 scripts/vf_social_intelligence.py --self-test\n"""\nfrom __future__ import annotations\n\nimport argparse\nimport json\nimport math\nimport sys\nfrom datetime import datetime, timezone\nfrom pathlib import Path\nfrom typing import Any\nfrom urllib.parse import urlparse\n\nROOT = Path(__file__).resolve().parents[1]\nPACKET_SCHEMA = ROOT / "packages" / "vfresearch" / "social-research-packet.schema.json"\nREFERENCE_SCHEMA = ROOT / "packages" / "vfresearch" / "reference-pattern.schema.json"\n\nSIGNAL_KEYS = (\n    "source_url",\n    "provider",\n    "author",\n    "published_at",\n    "observed_at",\n    "media_type",\n    "topic",\n    "hook_mechanic",\n    "visual_mechanic",\n    "narrative_mechanic",\n    "outlier_score",\n    "evidence_quality",\n    "metrics",\n)\n\n\ndef fail(msg: str, code: int = 2) -> None:\n    print(f"FAIL {msg}", file=sys.stderr)\n    raise SystemExit(code)\n\n\ndef now_utc() -> str:\n    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")\n\n\ndef is_public_http_url(value: Any) -> bool:\n    if not isinstance(value, str) or not value.strip():\n        return False\n    try:\n        parsed = urlparse(value.strip())\n    except ValueError:\n        return False\n    return parsed.scheme in {"http", "https"} and bool(parsed.netloc)\n\n\ndef finite_number(value: Any) -> float | int | None:\n    if isinstance(value, bool) or value is None:\n        return None\n    if isinstance(value, (int, float)) and math.isfinite(float(value)):\n        return value\n    if isinstance(value, str):\n        s = value.strip().replace(",", "")\n        if not s:\n            return None\n        try:\n            f = float(s)\n        except ValueError:\n            return None\n        if not math.isfinite(f):\n            return None\n        return int(f) if f.is_integer() else f\n    return None\n\n\ndef normalize_metrics(raw: Any) -> dict[str, float | int | None]:\n    if not isinstance(raw, dict):\n        return {}\n    out: dict[str, float | int | None] = {}\n    for key, value in raw.items():\n        if not isinstance(key, str) or not key.strip():\n            continue\n        if value is None:\n            out[key.strip()] = None\n            continue\n        parsed = finite_number(value)\n        if parsed is not None:\n            out[key.strip()] = parsed\n    return out\n\n\ndef normalize_signal(raw: dict[str, Any], default_provider: str = "unknown") -> dict[str, Any]:\n    url = raw.get("source_url") or raw.get("url") or raw.get("permalink")\n    if not is_public_http_url(url):\n        fail("signal requires public http(s) source_url")\n    provider = str(raw.get("provider") or default_provider or "unknown").strip() or "unknown"\n    observed_at = str(raw.get("observed_at") or raw.get("scraped_at") or now_utc()).strip()\n    out = {\n        "source_url": str(url).strip(),\n        "provider": provider,\n        "author": raw.get("author") or raw.get("username") or raw.get("handle"),\n        "published_at": raw.get("published_at") or raw.get("date") or raw.get("timestamp"),\n        "observed_at": observed_at,\n        "media_type": raw.get("media_type") or raw.get("type"),\n        "topic": raw.get("topic"),\n        "hook_mechanic": raw.get("hook_mechanic"),\n        "visual_mechanic": raw.get("visual_mechanic"),\n        "narrative_mechanic": raw.get("narrative_mechanic"),\n        "outlier_score": finite_number(raw.get("outlier_score")),\n        "evidence_quality": raw.get("evidence_quality"),\n        "metrics": normalize_metrics(raw.get("metrics") or {}),\n    }\n    return {k: out.get(k) for k in SIGNAL_KEYS}\n\n\ndef packet_from_raw(raw: Any, window_start: str, window_end: str, provider: str) -> dict[str, Any]:\n    if isinstance(raw, dict) and isinstance(raw.get("signals"), list):\n        rows = raw["signals"]\n        opportunities = raw.get("opportunities") or []\n        risks = raw.get("risks") or []\n    elif isinstance(raw, list):\n        rows = raw\n        opportunities = []\n        risks = []\n    else:\n        fail("input must be a list of signals or an object with signals[]")\n    signals = [normalize_signal(row, provider) for row in rows if isinstance(row, dict)]\n    sources = []\n    seen = set()\n    for s in signals:\n        key = (s["source_url"], s["provider"])\n        if key in seen:\n            continue\n        seen.add(key)\n        sources.append({\n            "url": s["source_url"],\n            "provider": s["provider"],\n            "observed_at": s["observed_at"],\n            "note": None,\n        })\n    return {\n        "schemaVersion": "1.0",\n        "window": {"start": window_start, "end": window_end},\n        "sources": sources,\n        "signals": signals,\n        "opportunities": opportunities,\n        "risks": risks,\n        "rules": {\n            "ownAccountCanonical": "instagram_mcp",\n            "publicExternalOnly": True,\n            "missingMetricIsNotZero": True,\n            "globalViralityScoreForbidden": True,\n        },\n    }\n\n\ndef validate_packet(packet: Any) -> list[str]:\n    errors: list[str] = []\n    if not isinstance(packet, dict):\n        return ["packet must be object"]\n    if packet.get("schemaVersion") != "1.0":\n        errors.append("schemaVersion must be 1.0")\n    window = packet.get("window")\n    if not isinstance(window, dict) or not window.get("start") or not window.get("end"):\n        errors.append("window.start and window.end required")\n    for key in ("sources", "signals", "opportunities", "risks"):\n        if not isinstance(packet.get(key), list):\n            errors.append(f"{key} must be array")\n    for i, signal in enumerate(packet.get("signals") or []):\n        if not isinstance(signal, dict):\n            errors.append(f"signals[{i}] must be object")\n            continue\n        if not is_public_http_url(signal.get("source_url")):\n            errors.append(f"signals[{i}].source_url must be public http(s)")\n        if not signal.get("provider"):\n            errors.append(f"signals[{i}].provider required")\n        if not signal.get("observed_at"):\n            errors.append(f"signals[{i}].observed_at required")\n        metrics = signal.get("metrics")\n        if not isinstance(metrics, dict):\n            errors.append(f"signals[{i}].metrics must be object")\n        else:\n            for mk, mv in metrics.items():\n                if mv is not None and finite_number(mv) is None:\n                    errors.append(f"signals[{i}].metrics.{mk} must be numeric or null")\n    return errors\n\n\ndef _segments(raw: Any, key: str) -> list[dict[str, Any]]:\n    value = raw.get(key) if isinstance(raw, dict) else None\n    return [x for x in (value or []) if isinstance(x, dict)]\n\n\ndef _time_values(items: list[dict[str, Any]], keys: tuple[str, ...]) -> list[float]:\n    out = []\n    for item in items:\n        for key in keys:\n            val = finite_number(item.get(key))\n            if val is not None:\n                out.append(float(val))\n                break\n    return out\n\n\ndef build_reference_pattern(raw: dict[str, Any]) -> dict[str, Any]:\n    url = raw.get("source_url") or raw.get("url")\n    if not is_public_http_url(url):\n        fail("reference requires public http(s) source_url")\n    transcript = _segments(raw, "transcript_segments")\n    events = _segments(raw, "visual_events")\n    duration = finite_number(raw.get("duration_seconds"))\n    if duration is None:\n        ends = _time_values(transcript, ("end", "end_seconds", "at")) + _time_values(events, ("end", "end_seconds", "at"))\n        duration = max(ends) if ends else None\n    spoken_starts = _time_values(transcript, ("start", "start_seconds", "at"))\n    visual_change_starts = [\n        float(v)\n        for e in events\n        if str(e.get("kind") or "").lower() in {"cut", "visual_change", "shot", "scene_change"}\n        for v in [finite_number(e.get("at") if e.get("at") is not None else e.get("start"))]\n        if v is not None\n    ]\n    reveal_times = [\n        float(v)\n        for e in events\n        if str(e.get("kind") or "").lower() == "reveal"\n        for v in [finite_number(e.get("at") if e.get("at") is not None else e.get("start"))]\n        if v is not None\n    ]\n    overlay_count = sum(1 for e in events if str(e.get("kind") or "").lower() in {"overlay", "text_overlay"})\n    mechanics = raw.get("mechanics") if isinstance(raw.get("mechanics"), dict) else {}\n    return {\n        "schemaVersion": "1.0",\n        "source_url": str(url).strip(),\n        "observed": {\n            "duration_seconds": duration,\n            "first_spoken_at_seconds": min(spoken_starts) if spoken_starts else None,\n            "first_visual_change_at_seconds": min(visual_change_starts) if visual_change_starts else None,\n            "event_count": len(events),\n            "overlay_count": overlay_count,\n            "reveal_at_seconds": min(reveal_times) if reveal_times else None,\n        },\n        "mechanics": {\n            "hook_mechanic": mechanics.get("hook_mechanic") or raw.get("hook_mechanic"),\n            "visual_mechanic": mechanics.get("visual_mechanic") or raw.get("visual_mechanic"),\n            "narrative_mechanic": mechanics.get("narrative_mechanic") or raw.get("narrative_mechanic"),\n            "cta_type": mechanics.get("cta_type") or raw.get("cta_type"),\n        },\n        "provenance": {\n            "provider": str(raw.get("provider") or "unknown"),\n            "captured_at": raw.get("captured_at") or now_utc(),\n            "raw_ref": raw.get("raw_ref"),\n        },\n        "copyingForbidden": True,\n        "rules": {\n            "mechanicsOnly": True,\n            "doNotCopyWording": True,\n            "doNotCopyBrandingOrFootage": True,\n        },\n    }\n\n\ndef save_json(path: Path, payload: Any) -> None:\n    path.parent.mkdir(parents=True, exist_ok=True)\n    path.write_text(json.dumps(payload, ensure_ascii=False, indent=2) + "\\n", encoding="utf-8")\n\n\ndef self_test() -> int:\n    sample = [{\n        "url": "https://example.com/reel/1",\n        "provider": "fixture",\n        "metrics": {"views": "123", "likes": None, "comments": "4"},\n    }]\n    packet = packet_from_raw(sample, "2026-09-07", "2026-09-14", "fixture")\n    errors = validate_packet(packet)\n    if errors:\n        print("FAIL self-test packet", errors, file=sys.stderr)\n        return 1\n    sig = packet["signals"][0]\n    if sig["metrics"]["views"] != 123 or sig["metrics"]["likes"] is not None:\n        print("FAIL self-test metric semantics", file=sys.stderr)\n        return 1\n    ref = build_reference_pattern({\n        "source_url": "https://example.com/reel/1",\n        "provider": "fixture",\n        "duration_seconds": 12,\n        "transcript_segments": [{"start": 0.4, "end": 3.0, "text": "x"}],\n        "visual_events": [{"kind": "cut", "at": 0.8}, {"kind": "reveal", "at": 8.2}, {"kind": "text_overlay", "at": 1.0}],\n    })\n    if ref["observed"]["first_visual_change_at_seconds"] != 0.8 or ref["observed"]["overlay_count"] != 1:\n        print("FAIL self-test reference pattern", file=sys.stderr)\n        return 1\n    print("OK social-intelligence self-test")\n    return 0\n\n\ndef main(argv: list[str] | None = None) -> int:\n    p = argparse.ArgumentParser(description=__doc__)\n    p.add_argument("--self-test", action="store_true")\n    sub = p.add_subparsers(dest="cmd")\n\n    n = sub.add_parser("normalize-signals")\n    n.add_argument("--input", required=True)\n    n.add_argument("--output", required=True)\n    n.add_argument("--window-start", required=True)\n    n.add_argument("--window-end", required=True)\n    n.add_argument("--provider", default="unknown")\n\n    v = sub.add_parser("validate-packet")\n    v.add_argument("path")\n\n    r = sub.add_parser("reference-pattern")\n    r.add_argument("--input", required=True)\n    r.add_argument("--output", required=True)\n\n    args = p.parse_args(argv)\n    if args.self_test:\n        return self_test()\n    if args.cmd == "normalize-signals":\n        raw = json.loads(Path(args.input).read_text(encoding="utf-8"))\n        packet = packet_from_raw(raw, args.window_start, args.window_end, args.provider)\n        errors = validate_packet(packet)\n        if errors:\n            fail("; ".join(errors))\n        save_json(Path(args.output), packet)\n        print(f"OK wrote {args.output} signals={len(packet[\'signals\'])}")\n        return 0\n    if args.cmd == "validate-packet":\n        packet = json.loads(Path(args.path).read_text(encoding="utf-8"))\n        errors = validate_packet(packet)\n        if errors:\n            for e in errors:\n                print(f"FAIL {e}", file=sys.stderr)\n            return 1\n        print(f"OK packet valid signals={len(packet[\'signals\'])}")\n        return 0\n    if args.cmd == "reference-pattern":\n        raw = json.loads(Path(args.input).read_text(encoding="utf-8"))\n        payload = build_reference_pattern(raw)\n        save_json(Path(args.output), payload)\n        print(f"OK wrote {args.output}")\n        return 0\n    p.print_help()\n    return 2\n\n\nif __name__ == "__main__":\n    sys.exit(main())\n'
sensor = '#!/usr/bin/env python3\n"""Validate Social Intelligence integration. No network. No send."""\nfrom __future__ import annotations\n\nimport json\nimport subprocess\nimport sys\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parents[1]\nDOC = ROOT / "packages" / "vfresearch" / "SOCIAL-INTELLIGENCE.md"\nPACKET_SCHEMA = ROOT / "packages" / "vfresearch" / "social-research-packet.schema.json"\nREFERENCE_SCHEMA = ROOT / "packages" / "vfresearch" / "reference-pattern.schema.json"\nSCRIPT = ROOT / "scripts" / "vf_social_intelligence.py"\nDECISION = ROOT / "packages" / "vfom" / "INSTAGRAM-CONTENT-DECISION.json"\nINSIGHTS = ROOT / "packages" / "vfinsights" / "scripts" / "vf_insights_loop.py"\nANNOTATIONS = ROOT / "packages" / "vfinsights" / "data" / "creative-annotations.csv"\nINSIGHTS_SKILL = ROOT / "packages" / "vfinsights" / "SKILL.md"\nRESEARCH_SKILL = ROOT / "packages" / "vfresearch" / "SKILL.md"\nCONTENT_SKILL = ROOT / ".cursor" / "skills" / "vf-content-sprint" / "SKILL.md"\nLINKS = ROOT / "packages" / "vfresearch" / "LINKS.json"\n\nEXPECTED_ANGLES = {\n    "actionable", "motivational", "analytical", "contrarian",\n    "observation", "x_vs_y", "present_vs_future", "listicle",\n}\n\n\ndef fail(msg: str) -> None:\n    print(f"FAIL {msg}", file=sys.stderr)\n    raise SystemExit(1)\n\n\ndef main() -> None:\n    for path in (DOC, PACKET_SCHEMA, REFERENCE_SCHEMA, SCRIPT, DECISION, INSIGHTS, ANNOTATIONS, INSIGHTS_SKILL, RESEARCH_SKILL, CONTENT_SKILL, LINKS):\n        if not path.is_file():\n            fail(f"missing {path.relative_to(ROOT)}")\n\n    for schema in (PACKET_SCHEMA, REFERENCE_SCHEMA):\n        data = json.loads(schema.read_text(encoding="utf-8"))\n        if data.get("type") != "object":\n            fail(f"{schema.name} must be object schema")\n\n    doc = DOC.read_text(encoding="utf-8")\n    for needle in (\n        "Instagram MCP remains canonical",\n        "public material",\n        "No cookies",\n        "Content Matrix",\n        "outlier_score: null",\n        "CREATIVE-PERFORMANCE-PROFILE.json",\n        "no composite virality score",\n    ):\n        if needle.lower() not in doc.lower():\n            fail(f"SOCIAL-INTELLIGENCE.md missing {needle}")\n\n    decision = json.loads(DECISION.read_text(encoding="utf-8"))\n    if decision.get("version", 0) < 2:\n        fail("INSTAGRAM-CONTENT-DECISION version must be >=2")\n    order = decision.get("order") or []\n    if not order or order[0] != "content_matrix":\n        fail("content_matrix must run before saturation_scan")\n    stage = (decision.get("stages") or {}).get("content_matrix") or {}\n    if stage.get("enabled") is not True:\n        fail("content_matrix must be enabled")\n    if set(stage.get("formats") or []) != EXPECTED_ANGLES:\n        fail("content_matrix must expose exact 8 angle families")\n    if stage.get("noPublishAuthority") is not True:\n        fail("content_matrix must have no publish authority")\n    required = ((decision.get("stages") or {}).get("final_quality_gate") or {}).get("requiredPrePublishStages") or []\n    if "content_matrix" not in required:\n        fail("final gate must require evidenced content_matrix stage/N-A")\n\n    insight_text = INSIGHTS.read_text(encoding="utf-8")\n    for needle in ("CREATIVE-PERFORMANCE-PROFILE.json", "creative-annotations.csv", "MIN_MEASURED_POSTS_FOR_RECOMMENDATION"):\n        if needle not in insight_text:\n            fail(f"vf_insights_loop missing {needle}")\n\n    content = CONTENT_SKILL.read_text(encoding="utf-8")\n    if "content_matrix" not in content or "SocialResearchPacket" not in content:\n        fail("vf-content-sprint must consume content_matrix + SocialResearchPacket")\n\n    research = RESEARCH_SKILL.read_text(encoding="utf-8")\n    if "SOCIAL-INTELLIGENCE.md" not in research:\n        fail("vfresearch SKILL must route Social Intelligence")\n\n    links = json.loads(LINKS.read_text(encoding="utf-8"))\n    ids = {x.get("id") for x in links.get("links") or []}\n    for need in ("charlie947-social-media-skills", "cporter202-automate-for-growth", "cporter202-social-media-scraping-apis"):\n        if need not in ids:\n            fail(f"LINKS.json missing {need}")\n\n    proc = subprocess.run([sys.executable, str(SCRIPT), "--self-test"], cwd=ROOT, text=True, capture_output=True)\n    if proc.returncode != 0:\n        fail((proc.stderr or proc.stdout or "self-test failed").strip())\n\n    print("OK social-intelligence integration")\n\n\nif __name__ == "__main__":\n    main()\n'
source_note = '# 2026-09-14 — Social Intelligence repo review → embedded patterns\n\nSources reviewed deeply:\n\n- https://github.com/charlie947/social-media-skills\n- https://github.com/cporter202/automate-for-growth\n- https://github.com/cporter202/social-media-scraping-apis\n\n## Embedded\n\n### `charlie947/social-media-skills`\n\nEmbedded patterns, not runtime:\n\n- evidence-backed Content Matrix as candidate expansion\n- measured-performance scoring principle\n- reference Reel mechanics extraction\n- date/source-verified niche research discipline\n\nRejected:\n\n- LinkedIn-specific assumptions\n- comment-gate / auto-DM behaviour\n- generic clickbait hook rules\n- duplicate voice/writer/analytics runtimes\n\n### `cporter202/automate-for-growth`\n\nEmbedded patterns only:\n\n- cheap candidate batching before expensive rendering\n- core-content → format-specific adaptation principle\n- measured feedback loop / A-B discipline\n\nRejected:\n\n- ViralWave dependency\n- generic virality score\n- bulk publishing\n- repeated personal-image “brand authority” mechanic\n\n### `cporter202/social-media-scraping-apis`\n\nUsed only as provider-discovery catalogue.\n\nRejected:\n\n- vendoring/cloning the catalogue\n- treating listed actors as trusted by default\n- scraping our own canonical Instagram metrics\n- authenticated/private scraping, cookies, engagement automation\n\n## VelvetOS mapping\n\n- external signals → `packages/vfresearch/SOCIAL-INTELLIGENCE.md`\n- normalization/reference mechanics → `scripts/vf_social_intelligence.py`\n- candidate matrix → `packages/vfom/INSTAGRAM-CONTENT-DECISION.json`\n- creative prior → `packages/vfinsights/CREATIVE-PERFORMANCE-PROFILE.json`\n- enforcement → `scripts/check-social-intelligence.py`\n\nNo new pack. No second runtime. No second scheduler. No second analytics source of truth.\n'
loop_new = '#!/usr/bin/env python3\n"""\nvf_insights_loop.py — Closed measurement-to-learning loop for VelvetOS.\nReads verified numbers from packages/vfinsights/data/posts.csv.\nPreferred source: Instagram MCP Insights via scripts/vf_insights_ingest.py.\nOwner paste remains a backup. Never invents a number that isn\'t in the source file.\n\nQualitative creative annotations are optional and live separately in\ndata/creative-annotations.csv so Instagram ingest never overwrites them.\n\nUsage:\n    python3 vf_insights_loop.py --init\n    python3 vf_insights_loop.py --data packages/vfinsights/data/posts.csv\n"""\nimport argparse, csv, json, statistics\nfrom pathlib import Path\n\nHERE = Path(__file__).resolve().parent\nDATA_DIR = HERE.parent / "data"\nTEMPLATE_PATH = DATA_DIR / "posts.csv"\nANNOTATIONS_PATH = DATA_DIR / "creative-annotations.csv"\nLEARNINGS_PATH = HERE.parent / "LEARNINGS.md"\nPROFILE_PATH = HERE.parent / "CREATIVE-PERFORMANCE-PROFILE.json"\nFIELDS = ["post_id", "date", "type", "reach", "likes", "saves", "comments", "caption_style", "views", "shares", "source"]\nANNOTATION_FIELDS = ["post_id", "hook_family", "visual_mechanic", "narrative_mechanic", "cta_type", "proof_type", "notes"]\nPROFILE_DIMENSIONS = ["type", "caption_style", "hook_family", "visual_mechanic", "narrative_mechanic", "cta_type", "proof_type"]\n\n# Do not recommend/promote a pattern below this measured-post sample size.\nMIN_MEASURED_POSTS_FOR_RECOMMENDATION = 3\nMIN_STYLES_OR_DISTINCT = 3\n\n\ndef init_template():\n    DATA_DIR.mkdir(parents=True, exist_ok=True)\n    if not TEMPLATE_PATH.exists():\n        with open(TEMPLATE_PATH, "w", newline="", encoding="utf-8") as f:\n            w = csv.writer(f)\n            w.writerow(FIELDS)\n            w.writerow(["DcqkjOLlYVX", "2026-08-30", "reel", "", "", "", "", "תהליך-קצר", "", "", ""])\n        print(f"wrote template: {TEMPLATE_PATH}")\n    else:\n        print(f"already exists: {TEMPLATE_PATH}")\n    if not ANNOTATIONS_PATH.exists():\n        with open(ANNOTATIONS_PATH, "w", newline="", encoding="utf-8") as f:\n            csv.writer(f).writerow(ANNOTATION_FIELDS)\n        print(f"wrote template: {ANNOTATIONS_PATH}")\n    print("Fill metrics via Instagram MCP or owner paste. Leave blank if unknown — do not guess.")\n\n\ndef load_rows(path):\n    """Load CSV rows. Preserve explicit 0 vs blank: blank → None metric; \'0\' stays 0."""\n    rows = []\n    with open(path, encoding="utf-8-sig") as f:\n        for row in csv.DictReader(f):\n            rows.append({k: (v if v is not None else "") for k, v in row.items()})\n            for k, v in list(rows[-1].items()):\n                if isinstance(v, str):\n                    rows[-1][k] = v.strip()\n    return rows\n\n\ndef load_annotations(path=ANNOTATIONS_PATH):\n    if not Path(path).is_file():\n        return {}\n    out = {}\n    with open(path, encoding="utf-8-sig") as f:\n        for raw in csv.DictReader(f):\n            post_id = (raw.get("post_id") or "").strip()\n            if not post_id:\n                continue\n            out[post_id] = {k: (raw.get(k) or "").strip() for k in ANNOTATION_FIELDS if k != "post_id"}\n    return out\n\n\ndef merge_annotations(rows, annotations):\n    merged = []\n    for row in rows:\n        item = dict(row)\n        item.update(annotations.get(item.get("post_id"), {}))\n        merged.append(item)\n    return merged\n\n\ndef to_float(v):\n    """Blank/missing → None (אין ספירה). Explicit \'0\' → 0.0 (preserved measured zero from MCP)."""\n    if v is None:\n        return None\n    s = str(v).strip()\n    if s == "":\n        return None\n    try:\n        return float(s)\n    except (TypeError, ValueError):\n        return None\n\n\ndef _rate(row, metric):\n    reach = to_float(row.get("reach"))\n    value = to_float(row.get(metric))\n    if reach is None or reach <= 0 or value is None:\n        return None\n    return value / reach\n\n\ndef _dimension_summary(measured, dimension):\n    buckets = {}\n    for row in measured:\n        value = (row.get(dimension) or "").strip()\n        if not value:\n            continue\n        buckets.setdefault(value, []).append(row)\n    summary = []\n    for value, items in buckets.items():\n        reaches = [to_float(r.get("reach")) for r in items]\n        reaches = [x for x in reaches if x is not None]\n        save_rates = [x for x in (_rate(r, "saves") for r in items) if x is not None]\n        share_rates = [x for x in (_rate(r, "shares") for r in items) if x is not None]\n        comment_rates = [x for x in (_rate(r, "comments") for r in items) if x is not None]\n        summary.append({\n            "value": value,\n            "n_posts": len(items),\n            "eligible_prior": len(items) >= MIN_MEASURED_POSTS_FOR_RECOMMENDATION,\n            "avg_reach": round(statistics.mean(reaches), 4) if reaches else None,\n            "avg_save_rate": round(statistics.mean(save_rates), 6) if save_rates else None,\n            "avg_share_rate": round(statistics.mean(share_rates), 6) if share_rates else None,\n            "avg_comment_rate": round(statistics.mean(comment_rates), 6) if comment_rates else None,\n        })\n    summary.sort(key=lambda x: (x["eligible_prior"], x["n_posts"], x["avg_reach"] or -1), reverse=True)\n    return summary\n\n\ndef analyze(rows):\n    measured = [r for r in rows if to_float(r.get("reach")) is not None]\n    unmeasured = [r for r in rows if to_float(r.get("reach")) is None]\n    by_style = {}\n    for r in measured:\n        style = r.get("caption_style") or "unknown"\n        reach = to_float(r["reach"])\n        if reach is None:\n            continue\n        saves = to_float(r.get("saves"))\n        # Existing field retained for backwards compatibility: this is save/reach when saves is measured.\n        engagement = (saves / reach) if (saves is not None and reach) else None\n        by_style.setdefault(style, []).append({"reach": reach, "engagement_rate": engagement})\n    style_summary = []\n    for style, items in by_style.items():\n        reaches = [i["reach"] for i in items]\n        rates = [i["engagement_rate"] for i in items if i["engagement_rate"] is not None]\n        style_summary.append({\n            "style": style,\n            "n_posts": len(items),\n            "avg_reach": round(statistics.mean(reaches), 1) if reaches else None,\n            "avg_engagement_rate": round(statistics.mean(rates), 4) if rates else None,\n        })\n    style_summary.sort(\n        key=lambda s: (\n            s["avg_engagement_rate"] is not None,\n            s["avg_engagement_rate"] or 0,\n            s["avg_reach"] or 0,\n        ),\n        reverse=True,\n    )\n    n_measured = len(measured)\n    can_recommend = n_measured >= MIN_MEASURED_POSTS_FOR_RECOMMENDATION and n_measured >= MIN_STYLES_OR_DISTINCT\n    dimensions = {dimension: _dimension_summary(measured, dimension) for dimension in PROFILE_DIMENSIONS}\n    return {\n        "n_total": len(rows),\n        "n_measured": n_measured,\n        "n_unmeasured": len(unmeasured),\n        "unmeasured_ids": [r["post_id"] for r in unmeasured],\n        "style_ranking": style_summary,\n        "can_recommend": can_recommend,\n        "min_measured_for_recommendation": MIN_MEASURED_POSTS_FOR_RECOMMENDATION,\n        "creative_dimensions": dimensions,\n    }\n\n\ndef write_profile(result):\n    eligible = []\n    for dimension, rows in result.get("creative_dimensions", {}).items():\n        for row in rows:\n            if row.get("eligible_prior"):\n                eligible.append({"dimension": dimension, **row})\n    payload = {\n        "schemaVersion": "1.0",\n        "source": {\n            "metrics": "packages/vfinsights/data/posts.csv",\n            "annotations": "packages/vfinsights/data/creative-annotations.csv",\n            "canonicalMetrics": "Instagram MCP verified Insights or owner-verified paste",\n        },\n        "measuredPosts": result["n_measured"],\n        "minimumMeasuredPostsPerPattern": MIN_MEASURED_POSTS_FOR_RECOMMENDATION,\n        "dimensions": result.get("creative_dimensions", {}),\n        "eligiblePriors": eligible,\n        "rules": {\n            "measuredEvidenceOnly": True,\n            "missingMetricIsNotZero": True,\n            "noCompositeViralityScore": True,\n            "priorNeverOverridesTruthRightsBrandOrQuality": True,\n        },\n    }\n    PROFILE_PATH.write_text(json.dumps(payload, ensure_ascii=False, indent=2) + "\\n", encoding="utf-8")\n    print(f"wrote {PROFILE_PATH}")\n\n\ndef write_learnings(result):\n    lines = ["# Learnings — closed measurement loop", "",\n              f"Measured {result[\'n_measured\']} of {result[\'n_total\']} posts. "\n              f"{result[\'n_unmeasured\']} still have no real number (excluded from ranking, not guessed).", "",\n              "Source preference: Instagram MCP verified Insights → `scripts/vf_insights_ingest.py` → `data/posts.csv`.",\n              "Creative annotations live separately in `data/creative-annotations.csv`; ingest never overwrites them.",\n              "Machine-readable measured prior: `CREATIVE-PERFORMANCE-PROFILE.json`.",\n              "Missing metric = אין ספירה / blank — never invent, never coerce unavailable → 0.",\n              "Explicit CSV `0` is preserved as measured zero (MCP returned 0); blank cell stays unknown.",\n              "The `source` column proves MCP origin when set to `instagram_mcp` (vs owner paste / blank).", ""]\n    if result["n_unmeasured"]:\n        lines.append("## Missing data (fetch via Instagram MCP before next brief)")\n        for pid in result["unmeasured_ids"]:\n            lines.append(f"- `{pid}` — אין ספירה (run get_media_insights / vf_insights_ingest)")\n        lines.append("")\n    if result["style_ranking"]:\n        lines.append("## Caption/format style ranked by measured save rate")\n        lines.append("")\n        lines.append("| style | posts | avg reach | avg save rate |")\n        lines.append("|---|---|---|---|")\n        for s in result["style_ranking"]:\n            er = s["avg_engagement_rate"] if s["avg_engagement_rate"] is not None else "אין ספירה"\n            lines.append(f"| {s[\'style\']} | {s[\'n_posts\']} | {s[\'avg_reach\']} | {er} |")\n        lines.append("")\n        if result.get("can_recommend"):\n            best = result["style_ranking"][0]\n            if best.get("avg_engagement_rate") is not None:\n                lines.append(\n                    f"**Recommendation for next post:** favor style `{best[\'style\']}` "\n                    f"(highest measured save rate so far: {best[\'avg_engagement_rate\']})."\n                )\n            else:\n                lines.append(\n                    f"**Recommendation for next post:** favor style `{best[\'style\']}` "\n                    f"(highest measured avg reach so far: {best[\'avg_reach\']}; save rate אין ספירה)."\n                )\n        else:\n            lines.append(\n                f"**Recommendation:** insufficient evidence — no format/style winner yet "\n                f"(need ≥{result.get(\'min_measured_for_recommendation\', MIN_MEASURED_POSTS_FOR_RECOMMENDATION)} "\n                f"measured posts; have {result[\'n_measured\']}). Ranking table kept for transparency."\n            )\n    else:\n        lines.append("No measured posts yet — ingest Instagram MCP Insights first.")\n        lines.append("")\n        lines.append("**Recommendation:** insufficient evidence — no format/style winner yet")\n    lines += [\n        "",\n        "## Creative-performance prior",\n        "",\n        "The profile may influence candidate/hook ranking only when a pattern itself has ≥3 measured posts.",\n        "It is not a global virality score and never overrides proof, truth, rights, brand fit, or fail-closed QA.",\n    ]\n    LEARNINGS_PATH.write_text("\\n".join(lines) + "\\n", encoding="utf-8")\n    print(f"wrote {LEARNINGS_PATH}")\n\n\ndef main():\n    ap = argparse.ArgumentParser()\n    ap.add_argument("--data", default=str(TEMPLATE_PATH))\n    ap.add_argument("--annotations", default=str(ANNOTATIONS_PATH))\n    ap.add_argument("--init", action="store_true")\n    args = ap.parse_args()\n    if args.init:\n        init_template()\n        return\n    path = Path(args.data)\n    if not path.exists():\n        print(f"no data file at {path} — run with --init first")\n        return\n    rows = load_rows(path)\n    annotations = load_annotations(Path(args.annotations))\n    rows = merge_annotations(rows, annotations)\n    result = analyze(rows)\n    write_learnings(result)\n    write_profile(result)\n    print(json.dumps({k: v for k, v in result.items() if k not in {"style_ranking", "creative_dimensions"}}, ensure_ascii=False, indent=2))\n\n\nif __name__ == "__main__":\n    main()\n'
